        "text": "2/3×3/4では、全体1を3×4＝12等分し、重なる2×3＝6区画を数えるため6/12＝1/2となる。一般に(a/b)×(c/d)=(a×c)/(b×d)。正の量に1未満の正の分数をかけると元の量より小さくなる。途中で約分しても値は保たれ、整数や帯分数を仮分数に直して同じ計算にまとめられる。",
