        "text": "2/3の3/4倍を、全体1の面積図で考えよう。 全体1の長方形を3列に等分し、2列分を選ぶ。 さらに4段に等分し、選んだ部分の3段分を取る。 全体3×4＝12区画のうち、重なりは2×3＝6区画。 6/12を約分して1/2。2/3×3/4＝1/2となる。 結論：1/2",
