        "text": "面積12cm²を保つ長方形で横3cm・縦4cmから横6cm・縦2cmへ移る。横2倍、縦1/2倍。続いて横2cm・縦6cmへ移ると、直前に対し横1/3倍、縦3倍。正の横xの各途中値に縦12/xを対応させ、常に面積12cm²を保つ。",
        "status": "verified",
