        "id": "c16",
        "text": "2、4、4、6、9の9を24に替えると、三つの代表値はどう変わる？ 平均値だけで「多くが8くらい」と言い切れる？ 合計が25から40に増えるので平均値は8になる。並びの中央と最も多い値はどちらも4のまま。多くが8とは言えず、分布も見る必要がある。 確認項目：平均値は5から8、中央値と最頻値は4のままと説明した。 / 平均だけではよく現れる値を断定できないと説明した。",
