        "text": "2、4、4、6、9を代表する値を調べよう。 小さい順に並べ、個数5、合計25を確かめる。 平均値は25÷5＝5。全部の量をならした値。 中央値は3番目の4。最頻値は二回現れる4。 ドットプロットで分布も見る。代表値一つだけでは散らばりを全て表せない。 結論：平均値5、中央値4、最頻値4",
