        "text": "記録0、1、2、3、3、4、5、5、6、7、8、10を幅2で分類する。度数が最多の階級は？ 正答：2以上4未満と4以上6未満。 2、3、3の3個と4、5、5の3個が並んで最多。 考える手がかり：一つに決めず、同じ最多の度数を全て探す。",
