        "text": "元の資料は12個なのに、度数の合計が13になった。まず何を確かめる？ 正答：境界の値を二重に数えるなど分類の重なりがないか。 元の12個を一度ずつ分類する。元の資料と表を一件ずつ対応させて調べる。 考える手がかり：元の資料を変えず、分類の過程を確かめる。",
