        "text": "資料の2と10を、どの階級へ入れるか理由と一緒に説明しよう。 同じ5が二つあれば、度数ではどう数える？ 境界の上端は含まないので、2も10もその数を下端とする階級へ入る。同じ5が二つあれば、4以上6未満へ二個分として加える。 確認項目：2は2以上4未満、10は10以上12未満と説明した。 / 同じ値でも二つの記録なので二個と数えた。",
