        "text": "0、1、2、3、3、4、5、5、6、7、8、10を幅2の度数分布表へ整理しよう。 0以上2未満から10以上12未満まで、幅2の六つの階級を作る。 各記録を一つずつ分類する。2は2以上4未満、10は10以上12未満へ入れる。 度数は順に2、3、3、2、1、1になる。 合計12を元の個数と照合し、同じ幅の柱の高さで度数を表す。 結論：度数は2、3、3、2、1、1。合計12個",
