        "text": "調べる目的を最初に決めるとして、統計的に考える基本の順を並べよう。 正答：集め方を計画する → 資料を集める → 表やグラフで分析する → 結論と限界をまとめる。 目的に合う計画で資料を集め、分析して結論へつなぐ。必要なら問いや計画へ戻って調べ直す。 考える手がかり：分析に必要な資料を、どう集めるかから考える。",
